// Тикет #81a2fb8e (81a2fb8ecbdb429cabc687b5) — עבר QA 13.10.2026, iPhone, TestFlight 1.0.0 (19).
// Факт 13.10: гость → «בואו נתחיל» → «הצטרפו אלינו» → «יצירת חשבון» → ссылка «תנאי השימוש» в строке
// «אני מאשר את תנאי השימוש ואת מדיניות הפרטיות» → экран «תנאי השימוש» («המסמך עדיין לא זמין») → кнопка «חזרה» (круглая, справа сверху)
// возвращает на «יצירת חשבון»; то же для «מדיניות הפרטיות».
// ⚠ Нужен ВЫХОД из аккаунта (экран регистрации виден только гостю): before — «התנתקות», after — вход снова (login()).
// @manual-check: направление стрелки в «חזרה» (в RTL — вправо) — по скрину; автоматически — положение кнопки (правый верхний угол) и возврат.
// Форма регистрации НЕ заполняется и НЕ отправляется.
import { driver, expect } from '@wdio/globals';
import { byText, byLabel, tapText, scrollToText } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn, logout } from '../../helpers/app.ts';
import { rectOf } from '../_lib/app-1310.ts';

async function restoreLogin() {
  for (let i = 0; i < 4; i++) {
    if (await isLoggedIn()) return;
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) break;
    if (await byText('כניסה דרך מספר נייד').isDisplayed().catch(() => false)) break;
    await driver.back();
  }
  await ensureAppReady();
}

async function openRegister() {
  if (await byText('יצירת חשבון').isDisplayed().catch(() => false)) return;
  const start = await byText('בואו נתחיל');
  if (await start.isDisplayed().catch(() => false)) await start.click();
  await (await byText('כניסה דרך מספר נייד')).waitForDisplayed({ timeout: 20000 });
  const join = await byText('הצטרפו אלינו');
  if (await join.isDisplayed().catch(() => false)) await join.click();
  else await (await byLabel('הצטרפו אלינו')).click();
  await (await byText('יצירת חשבון')).waitForDisplayed({ timeout: 20000 });
}

/** Ссылка внутри строки согласия: подпись доступности или текст. TODO калибровка: если ссылка не отдельный элемент — тап по координатам части строки. */
async function tapLegalLink(name: string) {
  await scrollToText('אני מאשר את');
  const byLbl = await byLabel(name);
  if (await byLbl.isDisplayed().catch(() => false)) return byLbl.click();
  return tapText(name);
}

async function checkLegalScreenBack(name: string) {
  await openRegister();
  await tapLegalLink(name);
  // Экран документа: заголовок и «המסמך עדיין לא זמין».
  await expect(byText(name)).toBeDisplayed({ wait: 15000 });
  await expect(byText('יצירת חשבון')).not.toBeDisplayed();
  await expect(byText('המסמך עדיין לא זמין')).toBeDisplayed();

  // «חזרה» — справа сверху (RTL).
  const back = await byLabel('חזרה');
  await expect(back).toBeDisplayed();
  const r = await rectOf(back);
  const { width, height } = await driver.getWindowSize();
  expect(r.x + r.width / 2).toBeGreaterThan(width / 2);
  expect(r.y).toBeLessThan(height * 0.2);
  console.log(`[RG-04] «${name}»: «חזרה» x=${r.x} y=${r.y}. @manual-check: стрелка смотрит вправо (RTL).`);

  // Возврат на «יצירת חשבון».
  await back.click();
  await expect(byText('יצירת חשבון')).toBeDisplayed({ wait: 15000 });
  await expect(byText('המסמך עדיין לא זמין')).not.toBeDisplayed();
}

describe('Регистрация: документы', () => {
  before(async () => { await logout(); });
  after(async () => { await restoreLogin(); });

  it('RG-04 «תנאי השימוש» и «מדיניות הפרטיות» из «יצירת חשבון» → «המסמך עדיין לא זמין» → «חזרה» (справа сверху) возвращает на «יצירת חשבון» #81a2fb8e @prod-safe @manual-check', async () => {
    await checkLegalScreenBack('תנאי השימוש');
    await checkLegalScreenBack('מדיניות הפרטיות');
  });
});
